def to_roman(n):
    """Convert an integer 1..3999 to its standard Roman numeral representation."""
    if not isinstance(n, int) or isinstance(n, bool) or n < 1 or n > 3999:
        raise ValueError(f"Invalid value for to_roman: {n!r}")

    values = (
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I'),
    )

    parts = []
    for val, sym in values:
        count, n = divmod(n, val)
        parts.append(sym * count)

    return ''.join(parts)


def from_roman(s):
    """Convert a standard Roman numeral string to its integer value."""
    if not isinstance(s, str) or len(s) == 0:
        raise ValueError(f"Invalid Roman numeral: {s!r}")

    numerals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    valid_chars = set(numerals.keys())

    if not all(c in valid_chars for c in s):
        raise ValueError(f"Invalid Roman numeral: {s!r}")

    # Parse into values
    values = [numerals[c] for c in s]

    # Check well-formedness by re-encoding and comparing
    result = 0
    for i, v in enumerate(values):
        if i + 1 < len(values) and v < values[i + 1]:
            result -= v
        else:
            result += v

    if result < 1 or result > 3999:
        raise ValueError(f"Invalid Roman numeral: {s!r}")

    if to_roman(result) != s:
        raise ValueError(f"Invalid Roman numeral: {s!r}")

    return result
